 const old=game.catalog.cards.find(c=>c.id===recipe.id);if(old&&old.instrument!==recipe.instrument)throw Error('Duplique cette recette avant de tester un changement d’instrument.');const copy={...structuredClone(recipe),starter:old?.starter||0,enabled:old?.enabled??true};if(old)Object.assign(old,copy);else game.catalog.cards.push(copy);
