function showResult(){const a=game.arena;$('#result-title').textContent=a.status==='stopped'?'Le show est arrêté':'Dernière note !';$('#result-body').innerHTML=`<b>${a.retired.length+game.fans.filter(f=>!f.hp).length} / ${a.config.total} conquis</b><p>${a.round} tours joués · tenue restante ${a.integrity}</p><p>${a.waiting.length} à l’entrée · ${a.queue.length} encore à venir</p>`;$('#result-dialog').showModal();}
$('#restart').onclick=reset;$('#result-restart').onclick=()=>{$('#result-dialog').close();reset();};$('#layout').onclick=()=>{cancel();editing=!editing;render();};$('#reduced').onchange=()=>draw();
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#queue-open').onclick=()=>{const a=game.arena,groups=[['Présents',game.fans],['À l’entrée',a.waiting],['À venir',a.queue],['Conquis sortis',a.retired]];$('#queue-body').innerHTML=groups.map(([name,fans])=>`<h3>${name} · ${fans.length}</h3>${fans.map(f=>`<div class="queue-row ${f.boss?'boss':''}"><b>#${f.rank}</b><span>${f.boss?'♛ ':''}${esc(f.name)}</span>${f.hp===undefined?'♥':f.hp+'/'+f.max}</div>`).join('')}`).join('');$('#queue-dialog').showModal();};
const field=(key,label,value,type='number',extra='')=>`<label>${label}<input data-config="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function workshop(){const c=config;$('#config-error').textContent='';const body=$('#workshop-body');
 if(tab==='show')body.innerHTML=`<div class="fields">${[['seed','Graine'],['total','Public total (boss inclus)'],['capacity','Actifs simultanés'],['initial','Présents au départ'],['arrivals','Arrivées par tour'],['integrity','Tenue du show'],['waitGrace','Tours de grâce à l’entrée'],['waitDamage','Dégât par impatient'],['frontDamage','Dégât par menace devant la scène'],['redDepth','Profondeur zone rouge (0,15 = 15 %)'],['advance','Avance vers la scène par tour'],['convergence','Convergence vers le centre (fraction)']].map(([k,l])=>field(k,l,c[k],'number','step="any"')).join('')}</div><p>${['entrancePressure','frontPressure'].map((k,i)=>`<label><input data-config="${k}" type="checkbox" ${c[k]?'checked':''}> ${i?'Pression zone rouge':'Pression entrée bloquée'}</label>`).join('')}</p>${c.songs.map((s,i)=>`<fieldset><legend>Chanson ${i+1}</legend><div class="fields">${field('songs.'+i+'.title','Titre',s.title,'text')}${field('songs.'+i+'.turns','Durée · 3 à 6 tours',s.turns)}<label>Style<select data-config="songs.${i}.style">${['Pop','Rock','Jazz','Folk','Ska','Métal'].map(x=>`<option ${s.style===x?'selected':''}>${x}</option>`).join('')}</select></label></div></fieldset>`).join('')}<h3>Boss dans la file</h3>${c.bosses.map((b,i)=>`<div class="fields"><label>Type<select data-config="bosses.${i}.type">${c.types.filter(t=>t.boss).map(t=>`<option value="${t.id}" ${t.id===b.type?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>${field('bosses.'+i+'.rank','Rang d’arrivée',b.rank)}<button data-remove-boss="${i}">Retirer</button></div>`).join('')}<button id="add-boss">Ajouter un boss</button><p>Les proportions des types ordinaires sont normalisées sur les places restantes. Les boss occupent les rangs exacts choisis.</p>`;
 if(tab==='public')body.innerHTML=`<button id="new-type">Nouveau type</button>${c.types.map((t,i)=>`<fieldset class="type-card" style="--color:${COLORS[t.effect]}"><legend>${esc(t.name)}</legend><div class="fields">${field('types.'+i+'.name','Nom',t.name,'text')}${field('types.'+i+'.hp','Cœurs nécessaires',t.hp)}${field('types.'+i+'.weight','Proportion relative (hors boss)',t.weight)}${field('types.'+i+'.mass','Masse · 2 = moitié du repoussement',t.mass,'number','step="0.1"')}<label>Effet de conquête<select data-config="types.${i}.effect">${Object.entries(TYPE_EFFECTS).map(([id,name])=>`<option value="${id}" ${t.effect===id?'selected':''}>${name}</option>`).join('')}</select></label>${field('types.'+i+'.effectValue','Valeur de l’effet (choc 1–5, projecteur 1–3, chœur 1–2)',t.effectValue)}<label>Intention<select data-config="types.${i}.intent">${Object.entries({bored:'Ennui',rhythm:'Attend du rythme',following:'Se laisse entraîner',attentive:'Attentif',distracted:'Distrait',variety:'Veut de la variété'}).map(([id,name])=>`<option value="${id}" ${id===t.intent?'selected':''}>${name}</option>`).join('')}</select></label><label><input type="checkbox" data-config="types.${i}.boss" ${t.boss?'checked':''}> Boss</label><label>Capacité<select data-config="types.${i}.ability">${Object.entries(ABILITIES).map(([id,name])=>`<option value="${id}" ${t.ability===id?'selected':''}>${name}</option>`).join('')}</select></label>${t.ability==='none'?'':field('types.'+i+'.period','Tous les X tours',t.period)+field('types.'+i+'.amount',t.ability==='tempo'?'Tempo retiré':'Distance d’avance',t.amount)+(t.ability==='advance'?field('types.'+i+'.radius','Rayon des voisins',t.radius,'number','step="0.1"'): '')}</div><p><button data-copy-type="${i}">Dupliquer</button> <button data-remove-type="${i}">Retirer</button></p></fieldset>`).join('')}`;
 if(tab==='cards')body.innerHTML=`<button id="open-cards">Ouvrir le constructeur de cartes</button><p>Dupliquer, retirer, composer des effets, tester ici. Seules les cibles Sol, Tout le public et Unique sont utilisées par le trio de départ.</p>${['voice','guitar','drums'].map((inst,i)=>`<fieldset><legend>${['Lia · Chant','Axel · Guitare','Sam · Batterie'][i]} · 5 exemplaires</legend><div class="fields">${content.decks[inst].map((id,n)=>`<label>Carte ${n+1}<select data-deck="${inst}:${n}">${content.catalog.cards.filter(c=>c.enabled&&[inst,'neutral'].includes(c.instrument)).map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`).join('')}</div></fieldset>`).join('')}`;
 if(tab==='show'||tab==='public'){try{const plan=queuePlan(c);body.insertAdjacentHTML('beforeend','<p><b>Répartition réelle :</b> '+c.types.map(t=>esc(t.name)+' '+plan.filter(id=>id===t.id).length).join(' · ')+'</p>');}catch{}}
 if(tab==='physics')body.innerHTML=`<fieldset><legend>Essais dans ce show</legend><div class="fields"><label>Énergie (0–3)<input type="number" data-resource="energy" min="0" max="3" value="${game.energy}"></label><label>Tempo (0–10)<input type="number" data-resource="tempo" min="0" max="10" value="${game.tempo}"></label><button id="redraw">Nouvelle main</button></div></fieldset><div class="fields">${field('waveSpeed','Vitesse de vague (unités/s)',c.waveSpeed)}${field('ghostOpacity','Opacité des conquis (0,25 = 25 %)',c.ghostOpacity,'number','step="0.05"')}${Object.entries({force:'Force globale',grip:'Résistance du sol',rebound:'Rebond',collisionRadius:'Rayon de collision',collisionPower:'Cœurs au contact',collisionThreshold:'Vitesse minimale du contact',hitStrength:'Repoussement musical'}).map(([k,l])=>`<label>${l}<input type="number" step="any" data-physics="${k}" value="${game.physics[k]}"></label>`).join('')}</div><p>Les paramètres physiques s’appliquent au show actuel. La disposition permet de déplacer les spectateurs à la souris ou au toucher. Les mouvements de fin de tour ne donnent aucun cœur.</p><button id="arrange">Déplacer les spectateurs</button>`;
}
$('#workshop').onclick=()=>{cancel();config=structuredClone(game.arena.config);workshop();$('#workshop-dialog').showModal();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;workshop();});
$('#workshop-body').onchange=event=>{const el=event.target;try{if(el.dataset.resource){setTestResources(game,el.dataset.resource==='energy'?Number(el.value):game.energy,el.dataset.resource==='tempo'?Number(el.value):game.tempo);save();render();}if(el.dataset.config){const path=el.dataset.config.split('.'),key=path.pop();let owner=config;for(const p of path)owner=owner[p];owner[key]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(['ability','effect','boss'].includes(key))workshop();}if(el.dataset.deck){const [inst,i]=el.dataset.deck.split(':');content.decks[inst][i]=el.value;}if(el.dataset.physics){const value=Number(el.value),settings=physicsSettings({...game.physics,[el.dataset.physics]:value});if(settings[el.dataset.physics]!==value)throw Error('Valeur physique hors limites.');game.physics=settings;save();}$('#config-error').textContent='';}catch(e){$('#config-error').textContent=e.message;}};
$('#workshop-body').onclick=event=>{const b=event.target.closest('button');if(!b)return;try{if(b.id==='redraw'){redrawTestHand(game);save();render();workshop();return;}if(b.id==='open-cards'){$('#workshop-dialog').close();editor.open();return;}if(b.id==='arrange'){$('#workshop-dialog').close();editing=true;render();return;}if(b.id==='new-type')config.types.push({...structuredClone(config.types[0]),id:'type-'+Date.now(),name:'Nouveau public',boss:false});if(b.dataset.copyType!==undefined)config.types.push({...structuredClone(config.types[Number(b.dataset.copyType)]),id:'type-'+Date.now(),name:'Copie '+config.types[Number(b.dataset.copyType)].name});if(b.dataset.removeType!==undefined){const t=config.types[Number(b.dataset.removeType)];if(config.bosses.some(b=>b.type===t.id))throw Error('Retire d’abord ce boss de la file.');config.types.splice(Number(b.dataset.removeType),1);}if(b.id==='add-boss'){const t=config.types.find(t=>t.boss);if(!t)throw Error('Crée un type boss d’abord.');config.bosses.push({type:t.id,rank:config.total});}if(b.dataset.removeBoss!==undefined)config.bosses.splice(Number(b.dataset.removeBoss),1);workshop();}catch(e){$('#config-error').textContent=e.message;}};
$('#apply').onclick=()=>{try{validateScenario(config);validateCatalog(content.catalog);const candidate=createArena(config,content);game=candidate;editorWorld={people:[],cardCatalog:content.catalog};cancel();save();$('#workshop-dialog').close();render();message('Scénario appliqué.');}catch(e){$('#config-error').textContent=e.message;}};
$('#export').onclick=()=>{try{validateScenario(config);const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,config,content,game},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='BandLive-arene.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('#config-error').textContent=e.message;}};
$('#import').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>10000000)throw Error('Fichier trop volumineux.');const value=JSON.parse(await file.text());validateScenario(value.config);validateCatalog(value.content.catalog);createArena(value.config,value.content);const restored=restoreArena(value.game);config=value.config;content=value.content;game=restored;editorWorld={people:[],cardCatalog:content.catalog};cancel();save();workshop();render();message('Prototype importé.');}catch(e){$('#config-error').textContent=e.message;}finally{event.target.value='';}};
window.addEventListener('resize',()=>{draw();if(selected&&point)showPreview();});render();save();if(!$('#message').textContent)message('Choisis une carte, puis vise le sol. Échap ou Reposer annule. Atelier règle le scénario.');
